"""Random Q15 pairs, including ones deliberately near the saturating corner
and ones exercising the rounding term."""


def generate(rng, count):
    builders = (_anything, _near_saturation, _small_values, _one_extreme)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, a, b, description=""):
    return {"name": name, "stdin": "%d %d\n" % (a, b),
            "description": description}


def _anything(rng, index):
    return _case("a random pair #%d" % index,
                 rng.randint(-32768, 32767), rng.randint(-32768, 32767))


def _near_saturation(rng, index):
    a = rng.choice((-32768, -32767, 32767))
    b = rng.choice((-32768, -32767, 32767))
    return _case("near the saturating corner #%d" % index, a, b,
                 "Both operands are close to +/-1.0, where the product can "
                 "overflow Q15's representable range.")


def _small_values(rng, index):
    return _case("small values, where rounding shows up #%d" % index,
                 rng.randint(-10, 10), rng.randint(-10, 10),
                 "The exact product is tiny -- whether you rounded or "
                 "truncated changes the answer.")


def _one_extreme(rng, index):
    a = rng.choice((-32768, 32767))
    return _case("one operand at an extreme #%d" % index,
                 a, rng.randint(-32768, 32767))
